const express = require('express');
const router = express.Router();

router.put('/api/tenants/:tenantId/security/fido2-policy', verifyTenantUser, async (req, res) => {
  const { tenantId } = req.params;
  const { requireResidentKey, allowedAaguids, userVerification } = req.body;

  if (req.user.tenantId !== tenantId || req.user.role !== 'TENANT_SECURITY_ADMIN') {
    return res.status(403).json({ error: 'Forbidden: only security administrators of this tenant can modify FIDO2 policy' });
  }

  const policy = await db.query(
    'UPDATE tenant_fido2_policies SET resident_key_required = $1, allowed_aaguids = $2, user_verification = $3 WHERE tenant_id = $4 RETURNING *',
    [requireResidentKey, JSON.stringify(allowedAaguids), userVerification, tenantId]
  );

  if (!policy.rowCount) return res.status(404).json({ error: 'Policy not found' });
  return res.json({ success: true, policy: policy.rows[0] });
});
